            // TODO API_TEST_START
            net.coobird.thumbnailator.ThumbnailParameter param = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder()
                .size(50, 50)
                .build();

            net.coobird.thumbnailator.tasks.io.BufferedImageSource source = new net.coobird.thumbnailator.tasks.io.BufferedImageSource(sourceImage);
            net.coobird.thumbnailator.tasks.io.BufferedImageSink sink = new net.coobird.thumbnailator.tasks.io.BufferedImageSink();

            net.coobird.thumbnailator.tasks.SourceSinkThumbnailTask<java.awt.image.BufferedImage, java.awt.image.BufferedImage> task = 
                new net.coobird.thumbnailator.tasks.SourceSinkThumbnailTask<>(param, source, sink);

            net.coobird.thumbnailator.Thumbnailator.createThumbnail(task);

            java.awt.image.BufferedImage result = sink.getSink();

